use crate::compiler::Instruction;use crate::worker::{TaskHandle,WorkerError,WorkerPool};use std::collections::HashMap;type Functions=HashMap<String,(Vec<String>,Vec<Instruction>)>;
pub struct Vm{pool:WorkerPool,out:Vec<String>}impl Vm{pub fn new(n:usize)->Result<Self,WorkerError>{Ok(Self{pool:WorkerPool::new(n)?,out:Vec::new()})}
pub fn run(&mut self,code:&[Instruction])->Result<&[String],String>{let mut f=Functions::new();for i in code{if let Instruction::DefineFunction(n,p,b)=i{if f.insert(n.clone(),(p.clone(),b.clone())).is_some(){return Err(format!("duplicate function '{n}'"));}}}let(params,main)=f.get("main").ok_or("missing main function")?;if !params.is_empty(){return Err("main function must not take parameters".into());}let(mut tasks,mut stack)=(Vec::new(),Vec::new());Self::exec(main,&mut stack,&mut Vec::new(),&mut tasks,&self.pool,&f,&mut self.out)?;Ok(&self.out)}
fn exec(code:&[Instruction],s:&mut Vec<i64>,l:&mut Vec<i64>,t:&mut Vec<Option<TaskHandle<i64>>>,pool:&WorkerPool,f:&Functions,out:&mut Vec<String>)->Result<(),String>{let mut pc=0;while pc<code.len(){match &code[pc]{
Instruction::Const(v)=>s.push(*v),Instruction::Load(i)=>s.push(*l.get(*i).ok_or("invalid local slot")?),Instruction::Store(i)=>{let v=s.pop().ok_or("stack underflow")?;if *i>=l.len(){l.resize(i+1,0);}l[*i]=v;},
Instruction::Add|Instruction::Sub|Instruction::Mul|Instruction::Div|Instruction::Eq|Instruction::Ne|Instruction::Lt|Instruction::Le|Instruction::Gt|Instruction::Ge=>{let b=s.pop().ok_or("stack underflow")?;let a=s.pop().ok_or("stack underflow")?;let v=match &code[pc]{Instruction::Add=>a.checked_add(b),Instruction::Sub=>a.checked_sub(b),Instruction::Mul=>a.checked_mul(b),Instruction::Div=>if b==0{None}else{a.checked_div(b)},Instruction::Eq=>Some((a==b)as i64),Instruction::Ne=>Some((a!=b)as i64),Instruction::Lt=>Some((a<b)as i64),Instruction::Le=>Some((a<=b)as i64),Instruction::Gt=>Some((a>b)as i64),Instruction::Ge=>Some((a>=b)as i64),_=>None}.ok_or("arithmetic error or division by zero")?;s.push(v);},
Instruction::Print=>out.push(s.pop().ok_or("stack underflow")?.to_string()),Instruction::Jump(target)=>{pc=*target;continue},Instruction::JumpIfFalse(target)=>{if s.pop().ok_or("stack underflow")?==0{pc=*target;continue}},
Instruction::Call(name,argc)=>{let(params,body)=f.get(name).ok_or_else(||format!("unknown function '{name}'"))?;if params.len()!=*argc{return Err(format!("function '{name}' expects {} arguments, got {argc}",params.len()));}let split=s.len().checked_sub(*argc).ok_or("stack underflow in call")?;let mut locals=s.split_off(split);let mut result=Vec::new();Self::exec(body,&mut result,&mut locals,t,pool,f,out)?;s.push(result.pop().unwrap_or(0));},
Instruction::Return=>return Ok(()),
Instruction::Submit(body)=>{let captures=l.clone();let body=body.clone();let functions=f.clone();let h=pool.submit(move||{let nested=WorkerPool::new(1)?;let(mut st,mut ts,mut output)=(Vec::new(),Vec::new(),Vec::new());let mut locals=captures;Self::exec(&body,&mut st,&mut locals,&mut ts,&nested,&functions,&mut output).map_err(|_|WorkerError::TaskPanicked)?;st.pop().ok_or(WorkerError::TaskPanicked)}).map_err(|e|e.to_string())?;t.push(Some(h));s.push((t.len()-1)as i64);},
Instruction::Wait=>{let id=s.pop().ok_or("stack underflow")?;if id<0{return Err("invalid task handle".into());}let h=t.get_mut(id as usize).and_then(Option::take).ok_or("invalid or reused task handle")?;s.push(h.wait().map_err(|e|e.to_string())?);},Instruction::DefineFunction(..)=>{},Instruction::Halt=>break,
}pc+=1;}Ok(())}}